        const retSemPg = await fetch(`${base}/${CNB}/retorno`, { method: 'POST', headers: H, body: JSON.stringify({ arquivo: [hdrRet, linhaRet(rcbRet.codrcb, 500, 0)].join('\r\n') }) });
