    // ══ APURAÇÃO PIS/COFINS — a TELA (FRMAPURACAOPISCOFINS) ══════════════════════════════════════════
    {
      const AP = 'fiscal/sped/apuracao-pc';
      const pgAp2 = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        const cod = Number((await pgAp2.query(`INSERT INTO apuracao_pc (idempresa, dataini, datafim, codoperador)
          VALUES (1, '2039-01-01', '2039-01-31', 7) RETURNING codapuracao_pc`)).rows[0].codapuracao_pc);
        // crédito de entrada: PIS 100 / COFINS 460 · débito de saída: PIS 160 / COFINS 700
        await pgAp2.query(`INSERT INTO apuracao_pc_det (codapuracao_pc, tipo, basecalculo, aliqpis, valorpis, aliqcofins, valorcofins, cst_pis) VALUES
          ($1,'C', 6060.61, 1.65, 100.00, 7.60, 460.00, 50),
          ($1,'D', 9696.97, 1.65, 160.00, 7.60, 700.00, 1)`, [cod]);

        const lista = (await (await fetch(`${base}/${AP}`, { headers: H })).json().catch(() => ([]))) as any[];
        const minha = (lista ?? []).find((x: any) => Number(x.codapuracao_pc) === cod);
        const det = (await (await fetch(`${base}/${AP}/${cod}`, { headers: H })).json().catch(() => ({}))) as any;
        check('APURAÇÃO PIS/COFINS §117.1 [o saldo, que é o que o contador procura]: a lista traz crédito e débito de cada apuração, e o detalhe separa os dois lados. O **a recolher** é `débito − crédito` por tributo (o M200/M600): PIS 160 − 100 = **60,00** e COFINS 700 − 460 = **240,00**',
          !!minha && Math.abs(Number(minha.credito) - 560) < 0.005 && Math.abs(Number(minha.debito) - 860) < 0.005
          && (det.itens ?? []).length === 2
          && Math.abs(Number(det.totais?.aRecolherPis) - 60) < 0.005
          && Math.abs(Number(det.totais?.aRecolherCofins) - 240) < 0.005
          && Number(det.totais?.creditoTransportarPis) === 0,
          { daLista: minha, totais: det.totais });

        // crédito MAIOR que o débito ⇒ transporta, e o a recolher é zero (não um número negativo)
        await pgAp2.query(`UPDATE apuracao_pc_det SET valorpis=500, valorcofins=900 WHERE codapuracao_pc=$1 AND tipo='C'`, [cod]);
        const det2 = (await (await fetch(`${base}/${AP}/${cod}`, { headers: H })).json().catch(() => ({}))) as any;
        check('APURAÇÃO PIS/COFINS §117.2 [crédito maior que o débito TRANSPORTA]: com crédito 500/900 contra débito 160/700, o a recolher é **zero** e o que sobra vira crédito a transportar (340 de PIS, 200 de COFINS) — é assim que o contador lê, e não como um valor a recolher negativo',
          Number(det2.totais?.aRecolherPis) === 0 && Number(det2.totais?.aRecolherCofins) === 0
          && Math.abs(Number(det2.totais?.creditoTransportarPis) - 340) < 0.005
          && Math.abs(Number(det2.totais?.creditoTransportarCofins) - 200) < 0.005,
          { totais: det2.totais });

        const semGrant = await fetch(`${base}/${AP}`, { headers: H_SEM_ACESSO });
        const naoExiste = await fetch(`${base}/${AP}/999777`, { headers: H });
        const del = await fetch(`${base}/${AP}/${cod}`, { method: 'DELETE', headers: H });
        const sobrou = (await pgAp2.query(`SELECT count(*)::int n FROM apuracao_pc_det WHERE codapuracao_pc=$1`, [cod])).rows[0] as any;
        check('APURAÇÃO PIS/COFINS §117.3: excluir é o "reabrir" do legado — a apuração é idempotente por período, então refazer é apurar de novo; a exclusão leva o detalhe junto e serve para quando o recorte muda. Sem grant, 403; apuração inexistente, 422',
          semGrant.status === 403 && naoExiste.status === 422
          && (del.status === 200 || del.status === 204) && Number(sobrou.n) === 0,
          { rbac: semGrant.status, inexistente: naoExiste.status, del: del.status, detalheRestante: sobrou.n });
      } finally {
        await pgAp2.end();
      }
    }

    // ══ EXTRATO DE FORNECEDORES (FRMEXTRATOFORNECEDORES) ═════════════════════════════════════════════
    {
      const EF = 'relatorios/extrato-fornecedores';
      const pgEf = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        // comprado em 05/01/2040, vence 05/02, PAGO em 10/03 — o par que separa o saldo retroativo
        const t1 = Number((await pgEf.query(`INSERT INTO apagar (codempresa, codparceiro, nrodup, duplicata, dtcompra, dtvenc, valor, quitada, tipodoc)
          VALUES (1, 2, 1, 'EF-PAGO', '2040-01-05', '2040-02-05', 1000.00, 'S', 'DP') RETURNING codapg`)).rows[0].codapg);
        await pgEf.query(`INSERT INTO apagar_bx (codapg, codempresa, dtpgto, valorpg, juros, acre_desc, indr)
                          VALUES ($1, 1, '2040-03-10', 1020.00, 20.00, 0, 'I')`, [t1]);
        // em aberto, vence 20/02/2040
        const t2 = Number((await pgEf.query(`INSERT INTO apagar (codempresa, codparceiro, nrodup, duplicata, dtcompra, dtvenc, valor, quitada, tipodoc)
          VALUES (1, 2, 2, 'EF-ABERTO', '2040-01-08', '2040-02-20', 300.00, 'N', 'DP') RETURNING codapg`)).rows[0].codapg);

        // ⚠️ o saldo em 28/02/2040: o título PAGO em março ainda era dívida naquele dia
        const saldoFev = (await (await fetch(`${base}/${EF}?dataIni=2040-02-28&modelo=SALDO`, { headers: H })).json().catch(() => ({}))) as any;
        const codsFev = (saldoFev.linhas ?? []).map((l: any) => Number(l.codapg));
        const saldoAbr = (await (await fetch(`${base}/${EF}?dataIni=2040-04-30&modelo=SALDO`, { headers: H })).json().catch(() => ({}))) as any;
        const codsAbr = (saldoAbr.linhas ?? []).map((l: any) => Number(l.codapg));
        check('EXTRATO FORNECEDORES §118.1 [o saldo retroativo olha a DATA DO PAGAMENTO, não o flag]: em 28/02/2040 o título pago só em 10/03 **ainda era dívida** — os dois aparecem, R$ 1.300,00. Em 30/04, com o pagamento já feito, sobra só o que continua aberto, R$ 300,00. É a diferença entre um saldo retroativo correto e um que conserta o passado com a informação de hoje',
          codsFev.includes(t1) && codsFev.includes(t2) && Math.abs(Number(saldoFev.totais?.valor) - 1300) < 0.005
          && !codsAbr.includes(t1) && codsAbr.includes(t2) && Math.abs(Number(saldoAbr.totais?.valor) - 300) < 0.005,
          { fev: codsFev, totaisFev: saldoFev.totais, abr: codsAbr, totaisAbr: saldoAbr.totais });

        const porVenc = (await (await fetch(`${base}/${EF}?dataIni=2040-02-01&dataFim=2040-02-28&modelo=PERIODO&base=VENCIMENTO`, { headers: H })).json().catch(() => ({}))) as any;
        const l1 = (porVenc.linhas ?? []).find((l: any) => Number(l.codapg) === t1);
        const l2 = (porVenc.linhas ?? []).find((l: any) => Number(l.codapg) === t2);
        check('EXTRATO FORNECEDORES §118.2 [a coluna que muda de significado]: `CASE quitada WHEN S THEN dtpgto ELSE dtvenc` — a data de referência do título QUITADO é a do **pagamento** (10/03) e a do aberto é a do **vencimento** (20/02). É intencional no legado, e a tela nomeia a coluna de acordo em vez de fingir que é só vencimento',
          String(l1?.data_referencia).slice(0, 10) === '2040-03-10'
          && String(l2?.data_referencia).slice(0, 10) === '2040-02-20',
          { quitado: l1?.data_referencia, aberto: l2?.data_referencia });

        const soAberto = (await (await fetch(`${base}/${EF}?dataIni=2040-01-01&dataFim=2040-12-31&modelo=PERIODO&situacao=ABERTO`, { headers: H })).json().catch(() => ({}))) as any;
        const semParceiro = (await (await fetch(`${base}/${EF}?dataIni=2040-01-01&dataFim=2040-12-31&modelo=PERIODO&parceiro=NAO%20EXISTE%20ESSE`, { headers: H })).json().catch(() => ({}))) as any;
        const semGrant = await fetch(`${base}/${EF}?dataIni=2040-02-28&modelo=SALDO`, { headers: H_SEM_ACESSO });
        const semFim = await fetch(`${base}/${EF}?dataIni=2040-02-01&modelo=PERIODO`, { headers: H });
        check('EXTRATO FORNECEDORES §118.3: situação filtra (só o aberto sobra); o nome do parceiro é tratado como NOME — no legado ele entra cru no SQL quando não tem `%` (`AND PA.RAZAO NESTLE`, que nem roda) — e o extrato por período exige as duas datas (400). Sem grant, 403',
          (soAberto.linhas ?? []).every((l: any) => l.quitada === 'N')
          && (soAberto.linhas ?? []).some((l: any) => Number(l.codapg) === t2)
          && (semParceiro.linhas ?? []).length === 0
          && semFim.status === 400 && semGrant.status === 403,
          { aberto: soAberto.linhas?.length, semParceiro: semParceiro.linhas?.length, semFim: semFim.status, rbac: semGrant.status });

        await pgEf.query(`DELETE FROM apagar_bx WHERE codapg IN ($1,$2)`, [t1, t2]);
        await pgEf.query(`DELETE FROM apagar WHERE codapg IN ($1,$2)`, [t1, t2]);
      } finally {
        await pgEf.end();
      }
    }

    // ══ ANÁLISE COMPRA × VENDA — CASA DE CARNE (FRMANALISECOMPRAVENDACASACARNE) ══════════════════════
    {
      const CC = 'relatorios/analise-casa-carne';
      const pgCc2 = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        // a PEÇA (decomposicao='S') e dois CORTES, 60% e 40%
        await pgCc2.query(`INSERT INTO produtos (idproduto, codbarra, descricao, unidade, ativo, codfor, aliquota, decomposicao) VALUES
          (991200,'7891200001200','TRASEIRO SMOKE CC','KG','S',1,'T01','S'),
          (991201,'7891200001201','PICANHA SMOKE CC','KG','S',1,'T01','N'),
          (991202,'7891200001202','COXAO SMOKE CC','KG','S',1,'T01','N') ON CONFLICT DO NOTHING`);
        await pgCc2.query(`INSERT INTO decomposicao (idproduto, idproduto_01, percentual) VALUES
          (991200, 991201, 60), (991200, 991202, 40)`);
        // compra: 100 kg da peça a R$ 20,00 ⇒ custo total R$ 2.000,00
        const nfc = Number((await pgCc2.query(`INSERT INTO nf (codnf, idempresa, tipo, modelo, nronf, serie, dtemissao, dtcontabil, tipoemissao, finalidade, cfop, idsituacao_nf, codparceiro, codparceiro_end, proc, totalnf, totalprod, cancelada)
          VALUES (991290, 1, 'E', '55', '991290', '1', '2041-05-10', '2041-05-10', '1', '1', '1102', 6, 2, NULL, 'S', 2000, 2000, 'N') RETURNING codnf`)).rows[0].codnf);
        await pgCc2.query(`INSERT INTO nf_prod (codnf, codproduto, quantidade, vrcusto, fatorembal, cfop)
                           VALUES ($1, 991200, 100, 20.00, 1, '1102')`, [nfc]);
        // venda dos cortes
        await pgCc2.query(`INSERT INTO vendas (idempresa, codvendas_legado, codproduto, dtvenda, qtde, vrvenda, vrcusto, cancelado, nropedido) VALUES
          (1, 772001, 991201, '2041-05-15', 55, 40.00, 20.00, 'N', '772001'),
          (1, 772002, 991202, '2041-05-16', 38, 25.00, 20.00, 'N', '772002')`);

        const r = (await (await fetch(`${base}/${CC}?dataIni=2041-05-01&dataFim=2041-05-31&produto=SMOKE%20CC`, { headers: H })).json().catch(() => ({}))) as any;
        const picanha = (r.linhas ?? []).find((l: any) => Number(l.codproduto) === 991201);
        const coxao = (r.linhas ?? []).find((l: any) => Number(l.codproduto) === 991202);
        check('ANÁLISE CASA DE CARNE §119.1 [o custo da peça vai para os cortes pelo PERCENTUAL, e divide por 100]: 100 kg a R$ 20,00 são R$ 2.000,00 de peça; 60% vão para a picanha (**R$ 1.200,00** e 60 kg) e 40% para o coxão (**R$ 800,00** e 40 kg). ⚠️ no legado o custo **não divide por 100** e ainda usa o valor UNITÁRIO — medido nas compras reais desde 2024, R$ 7.047,00 contra R$ 2.956,85 corretos, **138,3% a mais**',
          Math.abs(Number(picanha?.custo_compra) - 1200) < 0.01 && Math.abs(Number(picanha?.qtde_compra) - 60) < 0.001
          && Math.abs(Number(coxao?.custo_compra) - 800) < 0.01 && Math.abs(Number(coxao?.qtde_compra) - 40) < 0.001,
          { picanha, coxao });

        check('ANÁLISE CASA DE CARNE §119.2 [a margem de cada corte]: a picanha vendeu 55 kg por R$ 2.200,00 sobre R$ 1.200,00 de custo ⇒ **R$ 1.000,00**; o coxão, 38 kg por R$ 950,00 sobre R$ 800,00 ⇒ **R$ 150,00**. É a conta que diz se o rendimento do corte paga a peça',
          Math.abs(Number(picanha?.valor_venda) - 2200) < 0.01 && Math.abs(Number(picanha?.margem) - 1000) < 0.01
          && Math.abs(Number(coxao?.valor_venda) - 950) < 0.01 && Math.abs(Number(coxao?.margem) - 150) < 0.01,
          { picanha: [picanha?.valor_venda, picanha?.margem], coxao: [coxao?.valor_venda, coxao?.margem] });

        const soDec = (await (await fetch(`${base}/${CC}?dataIni=2041-05-01&dataFim=2041-05-31&somenteDecomposicao=S&produto=SMOKE%20CC`, { headers: H })).json().catch(() => ({}))) as any;
        const semGrant = await fetch(`${base}/${CC}?dataIni=2041-05-01&dataFim=2041-05-31`, { headers: H_SEM_ACESSO });
        const invertido = await fetch(`${base}/${CC}?dataIni=2041-05-31&dataFim=2041-05-01`, { headers: H });
        check('ANÁLISE CASA DE CARNE §119.3: o filtro de decomposição deixa só a peça e seus cortes (a peça aparece porque foi comprada, os cortes porque receberam rateio). Sem grant, 403; período invertido, 400',
          (soDec.linhas ?? []).length === 3 && semGrant.status === 403 && invertido.status === 400,
          { soDecomposicao: soDec.linhas?.length, rbac: semGrant.status, invertido: invertido.status });

        await pgCc2.query(`DELETE FROM vendas WHERE codproduto IN (991201,991202)`);
        await pgCc2.query(`DELETE FROM nf_prod WHERE codnf=$1`, [nfc]);
        await pgCc2.query(`DELETE FROM nf WHERE codnf=$1`, [nfc]);
        await pgCc2.query(`DELETE FROM decomposicao WHERE idproduto=991200`);
        await pgCc2.query(`DELETE FROM produtos WHERE idproduto IN (991200,991201,991202)`);
      } finally {
        await pgCc2.end();
      }
    }

    // ══ ANÁLISE DE VENDAS DE PRODUTOS (FRMRELATORIOVENDASDINAMICO) ═══════════════════════════════════
    {
      const VD = 'relatorios/vendas-dinamico';
      const pgVd = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        // um fornecedor INATIVO — é o que fazia o produto sumir no legado
        await pgVd.query(`INSERT INTO parceiros (codparceiro, razao, fantasia, ativado) VALUES (99310,'FORNECEDOR INATIVO VD','INATIVO VD','N') ON CONFLICT DO NOTHING`);
        await pgVd.query(`INSERT INTO produtos (idproduto, codbarra, descricao, unidade, ativo, ativo_compra, codfor, aliquota) VALUES
          (991300,'7891300001300','PROD VD COM FORN ATIVO','UN','S','S',1,'T01'),
          (991301,'7891300001301','PROD VD FORN INATIVO','UN','S','S',99310,'T01') ON CONFLICT DO NOTHING`);
        // duas compras do mesmo produto: a MAIS RECENTE tem código MENOR (é o caso dos 1.431 produtos)
        for (const [codnf, dt, custo] of [[991390, '2042-06-20', 30.00], [991391, '2042-06-10', 99.00]] as Array<[number, string, number]>) {
          await pgVd.query(`INSERT INTO nf (codnf, idempresa, tipo, modelo, nronf, serie, dtemissao, dtcontabil, tipoemissao, finalidade, cfop, idsituacao_nf, codparceiro, codparceiro_end, proc, totalnf, totalprod, cancelada)
            VALUES ($1, 1, 'E', '55', $4, '1', $2, $2, '1', '1', '1102', 6, 2, NULL, 'S', $3, $3, 'N')`, [codnf, dt, custo, String(codnf)]);
          await pgVd.query(`INSERT INTO nf_prod (codnf, codproduto, quantidade, vrcusto, fatorembal, cfop) VALUES ($1, 991300, 1, $2, 1, '1102')`, [codnf, custo]);
        }
        // uma nota CANCELADA, mais recente ainda e com custo absurdo
        await pgVd.query(`INSERT INTO nf (codnf, idempresa, tipo, modelo, nronf, serie, dtemissao, dtcontabil, tipoemissao, finalidade, cfop, idsituacao_nf, codparceiro, codparceiro_end, proc, totalnf, totalprod, cancelada)
          VALUES (991392, 1, 'E', '55', '991392', '1', '2042-06-25', '2042-06-25', '1', '1', '1102', 6, 2, NULL, 'S', 500, 500, 'S')`);
        await pgVd.query(`INSERT INTO nf_prod (codnf, codproduto, quantidade, vrcusto, fatorembal, cfop) VALUES (991392, 991300, 1, 500.00, 1, '1102')`);
        await pgVd.query(`INSERT INTO vendas (idempresa, codvendas_legado, codproduto, dtvenda, qtde, vrvenda, vrcusto, cancelado, nropedido) VALUES
          (1, 773001, 991300, '2042-06-22 10:00', 4, 50.00, 30.00, 'N', '773001')`);

        const r = (await (await fetch(`${base}/${VD}?dataIni=2042-06-01&dataFim=2042-06-30&produto=PROD%20VD`, { headers: H })).json().catch(() => ({}))) as any;
        const comAtivo = (r.linhas ?? []).find((l: any) => Number(l.codproduto) === 991300);
        const comInativo = (r.linhas ?? []).find((l: any) => Number(l.codproduto) === 991301);
        check('VENDAS DINÂMICO §120.1 [o `AND f.ativado = S` anulava o LEFT JOIN]: no legado, produto com fornecedor INATIVO (ou sem fornecedor) simplesmente sumia da análise — **228 produtos** dos 47.699 do cliente. Aqui ele aparece, com o fornecedor rotulado',
          !!comAtivo && !!comInativo && String(comInativo.nomefor) === 'FORNECEDOR INATIVO VD'
          && String(comInativo.fornecedor_ativo) === 'N',
          { comFornecedorAtivo: !!comAtivo, comFornecedorInativo: comInativo });

        check('VENDAS DINÂMICO §120.2 [o último custo vem da nota MAIS RECENTE, não do maior código]: a compra de 20/06 (código 991390, R$ 30,00) é mais nova que a de 10/06 (código 991391, R$ 99,00) — no legado, `MAX(CODNF)` pegaria a de 99,00, e isso acontece em **1.431 de 19.966 produtos**. E a nota CANCELADA de 25/06 (R$ 500,00) fica de fora, que o legado também não filtrava',
          String(comAtivo?.dtultimacompra).slice(0, 10) === '2042-06-20'
          && Math.abs(Number(comAtivo?.ultimocusto) - 30) < 0.005,
          { dtultimacompra: comAtivo?.dtultimacompra, ultimocusto: comAtivo?.ultimocusto });

        check('VENDAS DINÂMICO §120.3 [o giro do período]: 4 unidades a R$ 50,00 dão R$ 200,00 de venda acumulada e R$ 120,00 de custo (o legado trunca o total, e isso foi mantido); a última venda é 22/06',
          Math.abs(Number(comAtivo?.qtde) - 4) < 0.001
          && Math.abs(Number(comAtivo?.venda_acumulada) - 200) < 0.005
          && Math.abs(Number(comAtivo?.custo_acumulado) - 120) < 0.005
          && String(comAtivo?.dtultimavenda).slice(0, 10) === '2042-06-22'
          && Math.abs(Number(r.totais?.margem) - 80) < 0.005,
          { linha: comAtivo, totais: r.totais });

        const semGrant = await fetch(`${base}/${VD}?dataIni=2042-06-01&dataFim=2042-06-30`, { headers: H_SEM_ACESSO });
        const invertido = await fetch(`${base}/${VD}?dataIni=2042-06-30&dataFim=2042-06-01`, { headers: H });
        check('VENDAS DINÂMICO §120.4: sem grant, 403; período invertido, 400',
          semGrant.status === 403 && invertido.status === 400,
          { rbac: semGrant.status, invertido: invertido.status });

        await pgVd.query(`DELETE FROM vendas WHERE codproduto IN (991300,991301)`);
        await pgVd.query(`DELETE FROM nf_prod WHERE codnf IN (991390,991391,991392)`);
        await pgVd.query(`DELETE FROM nf WHERE codnf IN (991390,991391,991392)`);
        await pgVd.query(`DELETE FROM produtos WHERE idproduto IN (991300,991301)`);
        await pgVd.query(`DELETE FROM parceiros WHERE codparceiro=99310`);
      } finally {
        await pgVd.end();
      }
    }

    // ══ RELATÓRIO DE PREÇOS ALTERADOS (FRMRELPRECOSALTERADOS) ════════════════════════════════════════
    {
      const PA2 = 'relatorios/precos-alterados';
      const pgPa = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        await pgPa.query(`INSERT INTO produtos (idproduto, codbarra, descricao, unidade, ativo, codfor, aliquota) VALUES
          (991400,'7891400001400','PROD PA COM HIST','UN','S',1,'T01'),
          (991401,'7891400001401','PROD PA SEM HIST','UN','S',1,'T01') ON CONFLICT DO NOTHING`);
        // o histórico: o preço subiu de 12,99 para 17,90 (o valor vem como TEXTO, em pt-BR)
        const h = Number((await pgPa.query(`INSERT INTO historico_dinamico (tabela, chave, valor_chave, campo, valor_anterior, valor_atual, codoperador, codempresa, data, origem)
          VALUES ('MULTI_PRECO','IDPRODUTO','991400','VRVENDA','12,99','17,90', 7, 1, '2043-07-10', 'SMOKE') RETURNING codhistorico`)).rows[0].codhistorico);
        await pgPa.query(`INSERT INTO multi_preco (idproduto, idempresa, vrvenda, vrcusto, promocao, dtultprecoalterado, codhistorico)
                          VALUES (991400, 1, 17.90, 10.00, 'N', '2043-07-10', $1)`, [h]);
        // ⚠️ o MESMO tipo de alteração, mas SEM vínculo com o histórico — no legado este some do relatório
        await pgPa.query(`INSERT INTO multi_preco (idproduto, idempresa, vrvenda, vrcusto, promocao, dtultprecoalterado, codhistorico)
                          VALUES (991401, 1, 25.00, 12.00, 'N', '2043-07-11', NULL)`);

        const r = (await (await fetch(`${base}/${PA2}?dataIni=2043-07-01&dataFim=2043-07-31&produto=PROD%20PA`, { headers: H })).json().catch(() => ({}))) as any;
        const comH = (r.linhas ?? []).find((l: any) => Number(l.codproduto) === 991400);
        const semH = (r.linhas ?? []).find((l: any) => Number(l.codproduto) === 991401);
        check('PREÇOS ALTERADOS §121.1 [o INNER JOIN escondia mais da metade]: o legado junta `HISTORICO_DINAMICO` por INNER, e `MULTI_PRECO.CODHISTORICO` só existe em 43% das linhas — em agosto/2026 isso derrubava **328 de 594** alterações (55,2%). Aqui a alteração SEM histórico aparece, só sem o preço anterior: as duas linhas vêm, e a que tem histórico mostra de 12,99 para 17,90',
          (r.linhas ?? []).length === 2 && !!comH && !!semH
          && Math.abs(Number(comH.valor_anterior) - 12.99) < 0.005
          && Math.abs(Number(comH.valor) - 17.90) < 0.005
          && semH.valor_anterior === null && Math.abs(Number(semH.valor) - 25) < 0.005,
          { comHistorico: comH, semHistorico: semH });

        check('PREÇOS ALTERADOS §121.2 [de quanto para quanto]: 12,99 → 17,90 é **+R$ 4,91** e **+37,80%** — o valor anterior vem do histórico como TEXTO em pt-BR (`12,99`) e é convertido. O rodapé conta quantos subiram, caíram e quantos ficaram sem referência',
          Math.abs(Number(comH?.diferenca) - 4.91) < 0.005
          && Math.abs(Number(comH?.variacao_perc) - 37.8) < 0.05
          && Number(r.totais?.subiram) === 1 && Number(r.totais?.semAnterior) === 1,
          { diferenca: comH?.diferenca, variacao: comH?.variacao_perc, totais: r.totais });

        const semGrant = await fetch(`${base}/${PA2}?dataIni=2043-07-01&dataFim=2043-07-31`, { headers: H_SEM_ACESSO });
        const invertido = await fetch(`${base}/${PA2}?dataIni=2043-07-31&dataFim=2043-07-01`, { headers: H });
        const porLote = await fetch(`${base}/${PA2}?dataIni=2043-07-01&dataFim=2043-07-31&origem=LOTE`, { headers: H });
        check('PREÇOS ALTERADOS §121.3: a outra origem (o lote de alteração) responde; sem grant, 403; período invertido, 400',
          porLote.status === 200 && semGrant.status === 403 && invertido.status === 400,
          { lote: porLote.status, rbac: semGrant.status, invertido: invertido.status });

        await pgPa.query(`DELETE FROM multi_preco WHERE idproduto IN (991400,991401)`);
        await pgPa.query(`DELETE FROM historico_dinamico WHERE origem='SMOKE'`);
        await pgPa.query(`DELETE FROM produtos WHERE idproduto IN (991400,991401)`);
      } finally {
        await pgPa.end();
      }
    }

    // ══ ANÁLISE DE ITENS DA NOTA FISCAL (FRMRELANALISEITENSNF) ═══════════════════════════════════════
    {
      const IN2 = 'relatorios/analise-itens-nf';
      const pgIn = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        await pgIn.query(`INSERT INTO produtos (idproduto, codbarra, descricao, unidade, ativo, codfor, aliquota)
                          VALUES (991500,'7891500001500','PROD IN SMOKE','UN','S',1,'T01') ON CONFLICT DO NOTHING`);
        // três notas na mesma data: ENTRADA válida, SAÍDA e ENTRADA CANCELADA
        const notas: Array<[number, string, string]> = [[991590, 'E', 'N'], [991591, 'S', 'N'], [991592, 'E', 'S']];
        for (const [cod, tipo, canc] of notas) {
          await pgIn.query(`INSERT INTO nf (codnf, idempresa, tipo, modelo, nronf, serie, dtemissao, dtcontabil, tipoemissao, finalidade, cfop, idsituacao_nf, codparceiro, codparceiro_end, proc, totalnf, totalprod, cancelada)
            VALUES ($1, 1, $2, '55', $3, '1', '2044-08-10', '2044-08-10', '1', '1', '1102', 6, 2, NULL, 'S', 100, 100, $4)`, [cod, tipo, String(cod), canc]);
        }
        // o item da entrada válida: 10 × R$ 10,00 − desconto 5,00 = 95,00
        await pgIn.query(`INSERT INTO nf_prod (codnf, codproduto, quantidade, vrcusto, desconto, vrbasecalculo, vricm, vrbasest, vricmst, aliquota, cfop)
                          VALUES (991590, 991500, 10, 10.00, 5.00, 95.00, 17.10, 0, 0, 'T01', '1102')`);
        // ⚠️ o mesmo item numa SEGUNDA entrada, com DESCONTO NULO — no legado a linha sumia do total
        await pgIn.query(`INSERT INTO nf (codnf, idempresa, tipo, modelo, nronf, serie, dtemissao, dtcontabil, tipoemissao, finalidade, cfop, idsituacao_nf, codparceiro, codparceiro_end, proc, totalnf, totalprod, cancelada)
          VALUES (991593, 1, 'E', '55', '991593', '1', '2044-08-11', '2044-08-11', '1', '1', '1102', 6, 2, NULL, 'S', 40, 40, 'N')`);
        await pgIn.query(`INSERT INTO nf_prod (codnf, codproduto, quantidade, vrcusto, desconto, vrbasecalculo, vricm, vrbasest, vricmst, aliquota, cfop)
                          VALUES (991593, 991500, 4, 10.00, NULL, 40.00, 7.20, 0, 0, 'IST', '1102')`);
        await pgIn.query(`INSERT INTO nf_prod (codnf, codproduto, quantidade, vrcusto, desconto, vrbasecalculo, vricm, vrbasest, vricmst, aliquota, cfop)
                          VALUES (991591, 991500, 2, 30.00, 0, 60.00, 10.20, 0, 0, 'T01', '5102')`);
        await pgIn.query(`INSERT INTO nf_prod (codnf, codproduto, quantidade, vrcusto, desconto, vrbasecalculo, vricm, vrbasest, vricmst, aliquota, cfop)
                          VALUES (991592, 991500, 99, 99.00, 0, 9801.00, 1666.17, 0, 0, 'T01', '1102')`);

        const entradas = (await (await fetch(`${base}/${IN2}?dataIni=2044-08-01&dataFim=2044-08-31`, { headers: H })).json().catch(() => ({}))) as any;
        const todas = (await (await fetch(`${base}/${IN2}?dataIni=2044-08-01&dataFim=2044-08-31&tipo=TODAS&incluirCanceladas=S`, { headers: H })).json().catch(() => ({}))) as any;
        check('ANÁLISE ITENS NF §122.1 [o WHERE do legado só filtrava DATA]: sem empresa, sem tipo e sem cancelamento, ele somava 6.840 notas de entrada com **943 de saída** de **3 empresas** em agosto/2026. Aqui o padrão são só as ENTRADAS não canceladas — duas linhas; pedindo tudo, vêm as quatro (incluindo a saída e a cancelada, que sozinha traria R$ 9.801,00 para o total)',
          (entradas.linhas ?? []).length === 2 && (todas.linhas ?? []).length === 4,
          { soEntradas: entradas.linhas?.length, todas: todas.linhas?.length });

        const comDesc = (entradas.linhas ?? []).find((l: any) => Number(l.codnf) === 991590);
        const semDesc = (entradas.linhas ?? []).find((l: any) => Number(l.codnf) === 991593);
        check('ANÁLISE ITENS NF §122.2 [o desconto nulo não some mais]: `(QUANTIDADE × VRCUSTO) − DESCONTO` sem `COALESCE` vira NULL e o item desaparece do somatório — 23 linhas de 497.627. Aqui a linha com desconto nulo vale **40,00** e a com desconto vale **95,00**, somando **135,00**. E o item com alíquota `IST` conta como **isento** (40,00)',
          Math.abs(Number(comDesc?.total_custo) - 95) < 0.005
          && Math.abs(Number(semDesc?.total_custo) - 40) < 0.005
          && Math.abs(Number(entradas.totais?.custo) - 135) < 0.005
          && Math.abs(Number(entradas.totais?.isento) - 40) < 0.005
          && Math.abs(Number(entradas.totais?.icms) - 24.3) < 0.005,
          { comDesconto: comDesc?.total_custo, semDesconto: semDesc?.total_custo, totais: entradas.totais });

        const porNota = (await (await fetch(`${base}/${IN2}?dataIni=2044-08-01&dataFim=2044-08-31&codnf=991590`, { headers: H })).json().catch(() => ({}))) as any;
        const semGrant = await fetch(`${base}/${IN2}?dataIni=2044-08-01&dataFim=2044-08-31`, { headers: H_SEM_ACESSO });
        const invertido = await fetch(`${base}/${IN2}?dataIni=2044-08-31&dataFim=2044-08-01`, { headers: H });
        check('ANÁLISE ITENS NF §122.3: os filtros de nota, fornecedor, departamento, grupo e produto recortam; sem grant, 403; período invertido, 400',
          (porNota.linhas ?? []).length === 1 && semGrant.status === 403 && invertido.status === 400,
          { porNota: porNota.linhas?.length, rbac: semGrant.status, invertido: invertido.status });

        await pgIn.query(`DELETE FROM nf_prod WHERE codnf IN (991590,991591,991592,991593)`);
        await pgIn.query(`DELETE FROM nf WHERE codnf IN (991590,991591,991592,991593)`);
        await pgIn.query(`DELETE FROM produtos WHERE idproduto=991500`);
      } finally {
        await pgIn.end();
      }
    }

    // ══ FATURAMENTO DA NOTA (FRMFATURAMENTO2) ════════════════════════════════════════════════════════
    {
      const FT = 'compras/faturamento';
      const pgFt = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        const hojeIso = new Date().toISOString().slice(0, 10);
        const ontem = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
        const amanha = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
        // uma nota de ENTRADA processada, com quatro parcelas: vencida, hoje, a vencer e uma já faturada
        await pgFt.query(`INSERT INTO nf (codnf, idempresa, tipo, modelo, nronf, serie, dtemissao, dtcontabil, tipoemissao, finalidade, cfop, idsituacao_nf, codparceiro, codparceiro_end, proc, totalnf, totalprod, cancelada)
          VALUES (991690, 1, 'E', '55', '991690', '1', $1, $1, '1', '1', '1102', 6, 2, NULL, 'S', 1000, 1000, 'N')`, [ontem]);
        // ⚠️ uma nota NÃO processada: o legado exige PROC='S' e ela não deve aparecer
        await pgFt.query(`INSERT INTO nf (codnf, idempresa, tipo, modelo, nronf, serie, dtemissao, dtcontabil, tipoemissao, finalidade, cfop, idsituacao_nf, codparceiro, codparceiro_end, proc, totalnf, totalprod, cancelada)
          VALUES (991691, 1, 'E', '55', '991691', '1', $1, $1, '1', '1', '1102', 6, 2, NULL, 'N', 500, 500, 'N')`, [ontem]);
        await pgFt.query(`INSERT INTO faturamento (idnf, data, modalidade, valor, liberado, nrofatura, totalparcelasfatura) VALUES
          (991690, $1, 'A PAGAR', 250.00, 'N', 1, 4),
          (991690, $2, 'A PAGAR', 250.00, 'N', 2, 4),
          (991690, $3, 'APAGAR',  250.00, 'N', 3, 4),
          (991690, $2, 'A PAGAR', 250.00, 'S', 4, 4),
          (991691, $2, 'A PAGAR', 500.00, 'N', 1, 1),
          (991690, '0202-06-05', 'A PAGAR', 99.00, 'N', 5, 4)`, [ontem, hojeIso, amanha]);

        const aFaturar = (await (await fetch(`${base}/${FT}?dataIni=0001-01-01&dataFim=2100-12-31&base=PARCELA&tipo=E&liberado=N`, { headers: H })).json().catch(() => ({}))) as any;
        const codigos = (aFaturar.linhas ?? []).map((l: any) => Number(l.idnf));
        check('FATURAMENTO §123.1 [só nota PROCESSADA, e só o que falta faturar]: o legado exige `COALESCE(N.PROC,\'N\') = \'S\'` — a nota não processada (991691) fica de fora. E `liberado=N` traz só o que ainda não virou título: **4 parcelas** da nota 991690 (as três de vencimento mais a de ano inválido), não a que já foi liberada',
          (aFaturar.linhas ?? []).length === 4 && !codigos.includes(991691)
          && Number(aFaturar.totais?.notas) === 1,
          { linhas: aFaturar.linhas?.length, notas: aFaturar.totais?.notas, totais: aFaturar.totais });

        check('FATURAMENTO §123.2 [a legenda de três cores]: vencendo HOJE, ATRASADA e a vencer, cada parcela com a sua situação — é a legenda do original. E a parcela com o ano digitado errado (`0202`) é marcada: no cliente são **5 delas, R$ 11.193,35**, e o legado aceita qualquer data',
          Number(aFaturar.totais?.vencendoHoje) === 1
          // 2 atrasadas: a de ontem e a de ano 0202 — que é passado de verdade, então conta
          && Number(aFaturar.totais?.atrasadas) === 2
          && Number(aFaturar.totais?.dataInvalida) === 1
          && (aFaturar.linhas ?? []).some((l: any) => l.situacao === 'A_VENCER'),
          { totais: aFaturar.totais, situacoes: (aFaturar.linhas ?? []).map((l: any) => l.situacao) });

        const faturadas = (await (await fetch(`${base}/${FT}?dataIni=0001-01-01&dataFim=2100-12-31&base=PARCELA&tipo=E&liberado=S`, { headers: H })).json().catch(() => ({}))) as any;
        const modalidades = new Set((aFaturar.linhas ?? []).map((l: any) => l.modalidade_norm));
        const semGrant = await fetch(`${base}/${FT}?dataIni=2044-01-01&dataFim=2044-12-31`, { headers: H_SEM_ACESSO });
        check('FATURAMENTO §123.3: o outro lado (o já faturado) traz 1 parcela; as duas grafias da modalidade (`A PAGAR` e `APAGAR`, 45.897 e 7 no cliente) normalizam para a mesma; sem grant, 403',
          (faturadas.linhas ?? []).length === 1 && Number(faturadas.totais?.faturadas) === 1
          && modalidades.size === 1 && modalidades.has('APAGAR')
          && semGrant.status === 403,
          { faturadas: faturadas.linhas?.length, modalidades: [...modalidades], rbac: semGrant.status });

        await pgFt.query(`DELETE FROM faturamento WHERE idnf IN (991690,991691)`);
        await pgFt.query(`DELETE FROM nf WHERE codnf IN (991690,991691)`);
      } finally {
        await pgFt.end();
      }
    }

    // ══ MOVIMENTAÇÕES DO DIA (FRMMOVIMENTACOESDIA) ═══════════════════════════════════════════════════
    {
      const MD = 'relatorios/movimentacoes-dia';
      const pgMd = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        // baixa de A RECEBER e de A PAGAR no mesmo dia, pelo operador 7; e uma do operador 8
        const rcb = Number((await pgMd.query(`INSERT INTO areceber (codempresa, codparceiro, duplicata, dtvenda, dtvenc, valor, quitada, tipodoc)
          VALUES (1, 22, 'MD-1', '2045-04-01', '2045-04-20', 400.00, 'S', 'DP') RETURNING codrcb`)).rows[0].codrcb);
        await pgMd.query(`INSERT INTO areceber_bx (codrcb, codempresa, dtpgto, valorpg, juros, acre_desc, indr, codopbx, obs)
                          VALUES ($1, 1, '2045-04-15', 400.00, 0, 0, 'I', 7, 'RECEBIDO NO CAIXA')`, [rcb]);
        const apg = Number((await pgMd.query(`INSERT INTO apagar (codempresa, codparceiro, nrodup, dtcompra, dtvenc, valor, quitada, tipodoc)
          VALUES (1, 2, 1, '2045-04-02', '2045-04-18', 250.00, 'S', 'DP') RETURNING codapg`)).rows[0].codapg);
        await pgMd.query(`INSERT INTO apagar_bx (codapg, codempresa, dtpgto, valorpg, juros, acre_desc, indr, codopbx, obs)
                          VALUES ($1, 1, '2045-04-15', 250.00, 0, 0, 'I', 8, 'PAGO NO BANCO')`, [apg]);
        // ⚠️ uma baixa ESTORNADA (INDR='E') no mesmo dia — não pode entrar
        await pgMd.query(`INSERT INTO areceber_bx (codrcb, codempresa, dtpgto, valorpg, juros, acre_desc, indr, codopbx)
                          VALUES ($1, 1, '2045-04-15', 999.00, 0, 0, 'E', 7)`, [rcb]);
        await pgMd.query(`INSERT INTO historico (tabela, historico, codoperador, codempresa, data, coddoc)
          VALUES ('ARECEBER','BAIXA MANUAL CONFERIDA', 7, 1, '2045-04-15 10:00', $1),
                 ('APAGAR','PAGAMENTO AUTORIZADO', 8, 1, '2045-04-15 11:00', $2)`, [rcb, apg]);

        const dia = (await (await fetch(`${base}/${MD}?dataIni=2045-04-15&dataFim=2045-04-15`, { headers: H })).json().catch(() => ({}))) as any;
        check('MOVIMENTAÇÕES DO DIA §124.1 [os quatro blocos do dia]: recebidos, pagos, pedidos e o log de histórico no mesmo período. A baixa **estornada** (`INDR=E`) fica fora dos recebidos — R$ 400,00 e não R$ 1.399,00 —, e o histórico traz as duas linhas do log com o nome de quem fez',
          Number(dia.totais?.recebidos?.itens) === 1 && Math.abs(Number(dia.totais?.recebidos?.valor) - 400) < 0.005
          && Number(dia.totais?.pagos?.itens) === 1 && Math.abs(Number(dia.totais?.pagos?.valor) - 250) < 0.005
          && Number(dia.totais?.historico?.itens) === 2,
          { totais: dia.totais });

        const porOperador = (await (await fetch(`${base}/${MD}?dataIni=2045-04-15&dataFim=2045-04-15&codoperador=7`, { headers: H })).json().catch(() => ({}))) as any;
        check('MOVIMENTAÇÕES DO DIA §124.2 [o recorte por operador vale nos quatro blocos]: pedindo só o operador 7, sobra o recebimento dele e a linha de histórico dele — o pagamento e o log do operador 8 saem. É o "o que fulano fez hoje"',
          Number(porOperador.totais?.recebidos?.itens) === 1
          && Number(porOperador.totais?.pagos?.itens) === 0
          && Number(porOperador.totais?.historico?.itens) === 1,
          { totais: porOperador.totais });

        const semGrant = await fetch(`${base}/${MD}?dataIni=2045-04-15&dataFim=2045-04-15`, { headers: H_SEM_ACESSO });
        const invertido = await fetch(`${base}/${MD}?dataIni=2045-04-16&dataFim=2045-04-15`, { headers: H });
        check('MOVIMENTAÇÕES DO DIA §124.3: a tabela `historico` (455.264 linhas no cliente, até hoje) não existia no destino e entra com a migration — é a trilha em TEXTO, diferente do `historico_dinamico` campo a campo. Sem grant, 403; período invertido, 400',
          semGrant.status === 403 && invertido.status === 400,
          { rbac: semGrant.status, invertido: invertido.status });

        await pgMd.query(`DELETE FROM historico WHERE data::date = '2045-04-15'`);
        await pgMd.query(`DELETE FROM areceber_bx WHERE codrcb=$1`, [rcb]);
        await pgMd.query(`DELETE FROM apagar_bx WHERE codapg=$1`, [apg]);
        await pgMd.query(`DELETE FROM areceber WHERE codrcb=$1`, [rcb]);
        await pgMd.query(`DELETE FROM apagar WHERE codapg=$1`, [apg]);
      } finally {
        await pgMd.end();
      }
    }

    // ══ CADASTRO DO INDEXADOR TRIBUTÁRIO (FRMCADINDEXADORTRIBUTARIO) ═════════════════════════════════
    {
      const IT = 'cadastro/indexador-tributario';
      const pgIt = new Pool({ host: PG_CONN.host, port: PG_CONN.port, user: PG_CONN.user, password: PG_CONN.password, database: `${PG_CONN.databasePrefix}pinheirao` });
      try {
        const figura = { tp_cadastro: 'F', tp_figura: 'N', codfigurafiscal: 7799, origem: 'MG', destino: 'MG', codcfop: 1102, operacao: 'T', aliquota_dest: 18, icm_fonte: 12, mva: 45, redcom: 100, reducao: 100, aliquota_fem: 0, st_externo: 'N' };
        // três indexadores na MESMA figura, cada um com um discriminador diferente
        const porNcm  = await fetch(`${base}/${IT}`, { method: 'POST', headers: H, body: JSON.stringify({ ...figura, ncm: '99887766' }) });
        const porEan  = await fetch(`${base}/${IT}`, { method: 'POST', headers: H, body: JSON.stringify({ ...figura, ncm: '99887766', codbarra: '7899999000001', mva: 60 }) });
        const porParc = await fetch(`${base}/${IT}`, { method: 'POST', headers: H, body: JSON.stringify({ ...figura, ncm: '99887766', codparceiro: 2, mva: 30 }) });
        const semNada = await fetch(`${base}/${IT}`, { method: 'POST', headers: H, body: JSON.stringify(figura) });
        const dup     = await fetch(`${base}/${IT}`, { method: 'POST', headers: H, body: JSON.stringify({ ...figura, ncm: '99887766' }) });
        check('INDEXADOR §125.1 [a chave é COMPOSTA, e o mesmo NCM tem vários]: três indexadores convivem no mesmo NCM, um por discriminador (NCM puro, NCM+EAN, NCM+fornecedor) — no cliente são **12.053 indexadores para 1.075 NCMs**, e o `19053100` sozinho tem **285**. ⚠️ um indexador **sem nenhum** discriminador seria curinga universal no OR-null da resolução, e é recusado (400); e repetir figura+discriminadores é recusado também (422), porque o segundo nunca seria escolhido',
          porNcm.status === 201 && porEan.status === 201 && porParc.status === 201
          && semNada.status === 400 && dup.status === 422,
          { porNcm: porNcm.status, porEan: porEan.status, porParc: porParc.status, semNada: semNada.status, duplicado: dup.status });

        const lista = (await (await fetch(`${base}/${IT}?ncm=99887766`, { headers: H })).json().catch(() => ([]))) as any[];
        const codEan = Number(((await porEan.json().catch(() => ({}))) as any).codindexadortributario);
        check('INDEXADOR §125.2: a listagem por NCM traz os três, cada um com o seu MVA (45 no NCM puro, 60 no EAN, 30 no fornecedor) — é exatamente o material que a resolução multi-chave usa para desempatar por especificidade',
          (lista ?? []).length === 3
          && new Set((lista ?? []).map((l: any) => Number(l.mva))).size === 3,
          { achados: lista?.length, mvas: (lista ?? []).map((l: any) => Number(l.mva)) });

        const del = await fetch(`${base}/${IT}/${codEan}`, { method: 'DELETE', headers: H });
        const aindaLa = (await pgIt.query(`SELECT indr FROM indexador_tributario WHERE codindexadortributario=$1`, [codEan])).rows[0] as any;
        const listaDepois = (await (await fetch(`${base}/${IT}?ncm=99887766`, { headers: H })).json().catch(() => ([]))) as any[];
        const comExcluidos = (await (await fetch(`${base}/${IT}?ncm=99887766&incluirExcluidos=S`, { headers: H })).json().catch(() => ([]))) as any[];
        const semGrant = await fetch(`${base}/${IT}`, { method: 'POST', headers: H_SEM_ACESSO, body: JSON.stringify({ ...figura, ncm: '11111111' }) });
        check('INDEXADOR §125.3 [exclusão é LÓGICA]: `INDR = E`, como no legado — a linha continua na tabela (230 das 12.053 do cliente já estão assim) e some da lista, mas pode ser vista. Apagar de verdade mudaria a base de cálculo das notas já lançadas, que é o passado. Sem `BTNGRAVAR`, 403',
          (del.status === 200 || del.status === 204) && aindaLa?.indr === 'E'
          && (listaDepois ?? []).length === 2 && (comExcluidos ?? []).length === 3
          && semGrant.status === 403,
          { del: del.status, indr: aindaLa?.indr, semExcluidos: listaDepois?.length, comExcluidos: comExcluidos?.length, rbac: semGrant.status });

        await pgIt.query(`DELETE FROM indexador_tributario WHERE ncm IN ('99887766','11111111')`);
      } finally {
        await pgIt.end();
      }
    }

